  1→/**
  2→ * @cipherbox/core - Vault Key Blob v2 Format
  3→ *
  4→ * Binary envelope for storing ECIES-encrypted rootFolderKey on IPFS.
  5→ * This is a key-only blob — folder metadata is stored separately at
  6→ * the root folder's own IPNS name using standard v1 JSON format.
  7→ *
  8→ * Format: 0x02 | uint16_BE(key_len) | encrypted_key
  9→ *
 10→ * This module is pure byte manipulation with zero external dependencies
 11→ * (beyond types), making it easy to verify and port to other languages (Rust).
 12→ *
 13→ * Cross-platform test vectors in vault-blob-vectors.test.ts ensure binary
 14→ * compatibility between TypeScript and Rust implementations.
 15→ */
 16→
 17→/** Version byte for vault blob v2 format */
 18→export const BLOB_V2_VERSION = 0x02;
 19→
 20→/**
 21→ * Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
 22→ *
 23→ * v1 blobs start with 0x7B ('{' -- JSON object).
 24→ * v2 blobs start with 0x02 (version byte).
 25→ *
 26→ * Any blob that does not start with 0x02 is treated as v1 for backward
 27→ * compatibility -- this includes malformed blobs, which will fail at
 28→ * the JSON parse stage.
 29→ *
 30→ * @param blob - Raw bytes from IPFS
 31→ * @returns 1 for v1 JSON blobs, 2 for v2 binary blobs
 32→ */
 33→export function detectBlobVersion(blob: Uint8Array): 1 | 2 {
 34→  return blob.length > 0 && blob[0] === BLOB_V2_VERSION ? 2 : 1;
 35→}
 36→
 37→/**
 38→ * Serialize vault key blob v2.
 39→ *
 40→ * Constructs a binary envelope:
 41→ *   byte 0:    version (0x02)
 42→ *   bytes 1-2: key_len as big-endian uint16
 43→ *   bytes 3..: encrypted rootFolderKey (key_len bytes)
 44→ *
 45→ * @param encryptedRootFolderKey - ECIES-wrapped rootFolderKey (typically 129 bytes)
 46→ * @returns Complete v2 key blob ready for IPFS storage
 47→ */
 48→export function serializeVaultBlobV2(encryptedRootFolderKey: Uint8Array): Uint8Array {
 49→  const keyLen = encryptedRootFolderKey.length;
 50→  if (keyLen === 0) {
 51→    throw new Error('Encrypted key must not be empty for v2 blob');
 52→  }
 53→  if (keyLen > 0xffff) {
 54→    throw new Error(`Encrypted key too long for v2 blob (${keyLen} bytes, max ${0xffff})`);
 55→  }
 56→  const result = new Uint8Array(3 + keyLen);
 57→
 58→  // Version byte
 59→  result[0] = BLOB_V2_VERSION;
 60→  // Key length as big-endian uint16
 61→  result[1] = (keyLen >> 8) & 0xff;
 62→  result[2] = keyLen & 0xff;
 63→  // ECIES-encrypted rootFolderKey
 64→  result.set(encryptedRootFolderKey, 3);
 65→
 66→  return result;
 67→}
 68→
 69→/**
 70→ * Deserialize vault key blob v2 to extract the encrypted rootFolderKey.
 71→ *
 72→ * Validates the version byte and key_len field, then slices the key bytes.
 73→ *
 74→ * @param blob - Complete v2 key blob from IPFS
 75→ * @returns The ECIES-encrypted rootFolderKey
 76→ * @throws Error if blob is not v2 format, truncated, or key_len is invalid
 77→ */
 78→export function deserializeVaultBlobV2(blob: Uint8Array): Uint8Array {
 79→  if (blob.length < 3) {
 80→    throw new Error('Vault blob too short for v2 header (need at least 3 bytes)');
 81→  }
 82→
 83→  if (blob[0] !== BLOB_V2_VERSION) {
 84→    throw new Error('Not a v2 vault blob');
 85→  }
 86→
 87→  const keyLen = (blob[1] << 8) | blob[2];
 88→
 89→  if (keyLen === 0) {
 90→    throw new Error('Invalid v2 blob: encrypted key length must be > 0');
 91→  }
 92→
 93→  if (blob.length < 3 + keyLen) {
 94→    throw new Error(
 95→      `Vault blob too short for key (expected ${keyLen} bytes, have ${blob.length - 3})`
 96→    );
 97→  }
 98→
 99→  return blob.subarray(3, 3 + keyLen);
100→}
