50→function fromHex(hex: string): Uint8Array {
51→  const bytes = new Uint8Array(hex.length / 2);
52→  for (let i = 0; i < bytes.length; i++) {
53→    bytes[i] = parseInt(hex.substring(i * 2, i * 2 + 2), 16);
54→  }
55→  return bytes;
56→}
